INSERT INTO `sayfa_kvkk` (`id`, `baslik`, `icerik`) VALUES
(1, 'KVKK Aydınlatma Metni', '<h3 class=\"tarihce-alt-baslik\">1. Amaç</h3>\r\n\r\n<p>Veri sorumlusu olan Güzeller Mahallesi Bahar Cad. No:1 41400 Gebze/Kocaeli adresinde mukim Gebze Belediyesi (\"Belediye\" veya \"Kurum\"); belediyecilik hizmetleri esnasında topladığı aşağıda yer alan bir kısım kişisel verileri, 6698 sayılı Kişisel Verilerin Korunması Kanunu (\"KVK Kanunu\") ve sair mevzuat hükümlerine uygun şekilde işlenmesini amaçlamaktadır. Belediyemiz hizmetlerinden yararlanmanız esnasında bildirdiğiniz/bildireceğiniz kişisel verileriniz Kurumumuz tarafından \"Veri Sorumlusu\" sıfatıyla,</p>\r\n\r\n<ul class=\"kvkk-liste\">\r\n    <li>Kişisel verilerinizi işlenmelerini gerektiren amaç çerçevesinde ve bu amaç ile bağlantılı, sınırlı ve ölçülü şekilde,</li>\r\n    <li>Kurumumuza bildirdiğiniz veya bildirildiği şekliyle kişisel verilerin doğruluğunu ve en güncel halini koruyarak,</li>\r\n    <li>Kaydedileceğini, depolanacağını, muhafaza edileceğini, yeniden düzenleneceğini, kanunen bu kişisel verileri talep etmeye yetkili olan kurumlar ile paylaşılacağını ve KVK Kanunu\'nun öngördüğü şartlarda, yurtiçi üçüncü kişilere aktarılacağını, devredileceğini, sınıflandırılabileceğini ve KVK Kanunu\'nda sayılan sair şekillerde işlenebileceğini ve KVK Kanunu\'nda sayılan diğer işlemlere tabi tutulabileceğini bildiririz.</li>\r\n</ul>\r\n\r\n<p>İş bu Aydınlatma Metni ile belediyemiz tarafından yürütülen faaliyetlerin KVK Kanunu\'nda yer alan ilkelerle uyumlu olarak sürdürülmesi ve geliştirilmesi benimsenmiştir.</p>\r\n\r\n<h3 class=\"tarihce-alt-baslik\">2. Kişisel Verilerinin Toplanması ve Usulü</h3>\r\n\r\n<p>Kişisel verileriniz; https://www.gebze.bel.tr, belediye işlemleri, e-belediye işlemleri, Gebze Belediyesi çağrı merkezi, Gebze Belediyesi çözüm masası başvuruları, e-devlet ile ilişkili gerçekleştirilen işlemlerde e-devlet bağlantısı, fiziki başvuru, e-posta, çağrı merkezlerimiz aracılığı ile otomatik olmayan ve otomatik yöntemlerle toplanmaktadır. Kişisel verileriniz fiziki ortamda arşivlerde, dijital ortamda ise Gebze Belediyesi bünyesinde bulunan sunucularda saklanmaktadır.</p>\r\n\r\n<div class=\"kvkk-tablo-wrap\">\r\n<table class=\"kvkk-tablo\">\r\n<thead><tr><th>Veri Kategorisi</th><th>Açıklama</th></tr></thead>\r\n<tbody>\r\n<tr><td>Kimlik Verisi</td><td>Ad-soyad, T.C. kimlik numarası, vergi kimlik numarası, uyruk bilgisi, anne adı-baba adı, doğum yeri, doğum tarihi, cinsiyet gibi bilgileri içeren ehliyet, nüfus cüzdanı, araç ruhsatı suretleri gibi belgeler, yabancı kimlik no, pasaport no ile imza/paraf bilgisi, ticaret sicil numarası, abonelik numaraları, askerlik durum belgesi, evlenme beyannamesi</td></tr>\r\n<tr><td>İletişim Verisi</td><td>Telefon numarası, faks, açık adres bilgisi, ikametgah belgesi, sosyal medya hesapları, ülke, şehir, e-posta adresi (dâhili numarası ve kurumsal e-posta adresi dâhil)</td></tr>\r\n<tr><td>Finans Verileri</td><td>Fatura, dekont, kredi dökümü, SGK hizmet dökümü, SGK son bordrosu, ödeme ve finans bilgileri (banka adı, banka hesabı, IBAN), malvarlığı bilgileri (tapu bilgileri), fakirlik belgesi, belediyeye olan borç bilgileri, sosyal yardımlara ilişkin bilgiler, emlak beyanı, gelir durumuna ilişkin bilgiler ve belgeler (fakirlik belgesi vb.)</td></tr>\r\n<tr><td>Fiziksel Mekân Güvenlik Verisi</td><td>Fiziksel mekâna girişte, fiziksel mekânın içerisinde kalış sırasında alınan kamera kayıtları</td></tr>\r\n<tr><td>Sağlık Verisi</td><td>Sağlık raporu, engelli raporu, kan grubu</td></tr>\r\n<tr><td>Mesleki Deneyim Verisi</td><td>Diploma, öğrenim durumu, mesleği, eğitim bilgileri, iş güvenliği bilgisi, oda kayıt belgeler, ustalık belgesi, okul ve sınıf, özgeçmiş</td></tr>\r\n<tr><td>Hukuki İşlem Verisi</td><td>Veraset ilamı, icra bilgileri, dava dosyaları kapsamındaki bilgi ve belgeler</td></tr>\r\n<tr><td>Görsel ve İşitsel Kayıt Verisi</td><td>Fotoğraf, video kaydı</td></tr>\r\n<tr><td>Dernek Üyeliği Verisi</td><td>Dernek üyelik bilgisi</td></tr>\r\n<tr><td>Diğer Kişisel Veriler</td><td>Vekalet belgesi, hijyen belgesi, itfaiye raporu, desarj raporu, çed görüşü, kira sözleşmesi, iş güvenliği raporu, hekim ve uzman sözleşmesi, kapasite raporu, motor tesisat beyan belgesi, mesul müdürlük belgesi, sanayi sicil belgesi, araç plakası, kiralanan yere ilişkin bilgiler, noter tasdikli imza sirküleri, ukome izin belgesi, ticaret sicil belgesi, velinin muvaffakat belgesi, muvaffakatname, iş yeri açma ve çalıştırma ruhsat bilgisi</td></tr>\r\n<tr><td>Ceza Mahkumiyeti ve Güvenlik Verisi</td><td>Adli sicil kaydı, cezaevi müddetnamesi, ceza mahkumiyet ve güvenlik tedbirleri</td></tr>\r\n<tr><td>Biyometrik Veri</td><td>Parmak izi</td></tr>\r\n<tr><td>Kılık ve Kıyafet Verisi</td><td>Beden bilgileri</td></tr>\r\n<tr><td>Siyasi Düşünce Verisi</td><td>Siyasi parti üyeliği</td></tr>\r\n</tbody>\r\n</table>\r\n</div>\r\n\r\n<h3 class=\"tarihce-alt-baslik\">3. Kişisel Verilerin İşlenme Amaçları ve Hukuki Sebepler</h3>\r\n\r\n<p>Kişisel Verileriniz, Kurumumuz tarafından aşağıda belirtilen amaçlar ve hukuki sebepler doğrultusunda, işlenebilir. Kişisel verilerinizin işlenme amacında herhangi bir değişiklik olması halinde tarafınızdan ayrıca izin alınacaktır. Belediyecilik hizmetlerimiz kapsamında işlenen kişisel verileriniz; kanunlarda açıkça öngörülmesi, bir sözleşmenin kurulması veya ifasıyla doğrudan doğruya ilgili olması kaydıyla sözleşmenin taraflarına ait kişisel verilerin işlenmesinin gerekli olması, hukuki yükümlülüğümüzün yerine getirilebilmesi için veri işlemenin zorunlu olması, bir hakkın tesisi kullanılması veya korunması için veri işlemenin zorunlu olması, ilgili kişinin temel hak ve özgürlüklerine zarar vermemek kaydıyla meşru menfaatimiz için veri işlenmesinin zorunlu olması ve veri işleme için açık rızanın zorunlu olması sebepleri aşağıda yer alan amaçlar dahilinde işlenmektedir.</p>\r\n\r\n<ul class=\"kvkk-liste\">\r\n<li>İmar, su ve kanalizasyon, ulaşım gibi kentsel alt yapı; coğrafî ve kent bilgi sistemleri; çevre ve çevre sağlığı, temizlik ve katı atık; zabıta, itfaiye, acil yardım, kurtarma ve ambulans; şehir içi trafik; defin ve mezarlıklar; ağaçlandırma, park ve yeşil alanlar; konut; kültür ve sanat, turizm ve tanıtım, gençlik ve spor meslek ve beceri kazandırma; ekonomi ve ticaretin geliştirilmesi hizmetlerini yapmak veya yaptırmak,</li>\r\n<li>Belediyeler de mali durumları ve hizmet önceliklerini değerlendirerek kadınlar ve çocuklar için konukevleri açmak,</li>\r\n<li>Devlete ait her derecedeki okul binalarının inşaatı ile bakım ve onarımını yapmak veya yaptırmak,</li>\r\n<li>Her türlü araç, gereç ve malzeme ihtiyaçlarını karşılamak,</li>\r\n<li>Sağlıkla ilgili her türlü tesisi açabilir ve işletebilir; mabetlerin yapımı, bakımı, onarımını yapmak,</li>\r\n<li>Kültür ve tabiat varlıkları ile tarihî dokunun ve kent tarihi bakımından önem taşıyan mekânların ve işlevlerinin korunmasını sağlamak, bu amaçla bakım ve onarımını yapmak, korunması mümkün olmayanları aslına uygun olarak yeniden inşa etmek,</li>\r\n<li>Gerektiğinde, sporu teşvik etmek amacıyla gençlere spor malzemesi vermek, amatör spor kulüplerine ayni ve nakdî yardım yapar ve gerekli desteği sağlamak,</li>\r\n<li>Her türlü amatör spor karşılaşmaları düzenlemek,</li>\r\n<li>Yurt içi ve yurt dışı müsabakalarda üstün başarı gösteren veya derece alan öğrencilere, sporculara, teknik yöneticilere ve antrenörlere belediye meclisi kararıyla ödül vermek,</li>\r\n<li>Gıda bankacılığı yapmak,</li>\r\n<li>Belde sakinlerinin mahallî müşterek nitelikteki ihtiyaçlarını karşılamak amacıyla her türlü faaliyet ve girişimde bulunmak,</li>\r\n<li>Kanunların belediyeye verdiği yetki çerçevesinde yönetmelik çıkarmak, belediye yasakları koymak ve uygulamak, kanunlarda belirtilen cezaları vermek,</li>\r\n<li>Gerçek ve tüzel kişilerin faaliyetleri ile ilgili olarak kanunlarda belirtilen izin veya ruhsatı vermek,</li>\r\n<li>Özel kanunları gereğince belediyeye ait vergi, resim, harç, katkı ve katılma paylarının tarh, tahakkuk ve tahsilini yapmak; vergi, resim ve harç dışındaki özel hukuk hükümlerine göre tahsili gereken doğal gaz, su, atık su ve hizmet karşılığı alacakların tahsilini yapmak veya yaptırmak,</li>\r\n<li>Müktesep haklar saklı kalmak üzere; içme, kullanma ve endüstri suyu sağlamak; atık su ve yağmur suyunun uzaklaştırılmasını sağlamak; bunlar için gerekli tesisleri kurmak, kurdurmak, işletmek ve işlettirmek; kaynak sularını işletmek veya işlettirmek,</li>\r\n<li>Toplu taşıma yapmak; bu amaçla otobüs, deniz ve su ulaşım araçları, tünel, raylı sistem dâhil her türlü toplu taşıma sistemlerini kurmak, kurdurmak, işletmek ve işlettirmek,</li>\r\n<li>Katı atıkların toplanması, taşınması, ayrıştırılması, geri kazanımı, ortadan kaldırılması ve depolanması ile ilgili bütün hizmetleri yapmak ve yaptırmak,</li>\r\n<li>Mahallî müşterek nitelikteki hizmetlerin yerine getirilmesi amacıyla, belediye ve mücavir alan sınırları içerisinde taşınmaz almak, kamulaştırmak, satmak, kiralamak veya kiraya vermek, trampa etmek, tahsis etmek, bunlar üzerinde sınırlı aynî hak tesis etmek,</li>\r\n<li>Borç almak, bağış kabul etmek,</li>\r\n<li>Toptancı ve perakendeci hâlleri, otobüs terminali, fuar alanı, mezbaha, ilgili mevzuata göre yat limanı ve iskele kurmak, kurdurmak, işletmek, işlettirmek veya bu yerlerin gerçek ve tüzel kişilerce açılmasına izin vermek,</li>\r\n<li>Vergi, resim ve harçlar dışında kalan dava konusu uyuşmazlıkların anlaşmayla tasfiyesine karar vermek,</li>\r\n<li>Gayrisıhhî müesseseler ile umuma açık istirahat ve eğlence yerlerini ruhsatlandırmak ve denetlemek,</li>\r\n<li>Beldede ekonomi ve ticaretin geliştirilmesi ve kayıt altına alınması amacıyla izinsiz satış yapan seyyar satıcıları faaliyetten men etmek, izinsiz satış yapan seyyar satıcıların faaliyetten men edilmesi sonucu, cezası ödenmeyerek iki gün içinde geri alınmayan gıda maddelerini gıda bankalarına, cezası ödenmeyerek otuz gün içinde geri alınmayan gıda dışı malları yoksullara vermek,</li>\r\n<li>Reklam panoları ve tanıtıcı tabelalar konusunda standartlar getirmek,</li>\r\n<li>Gayrisıhhî işyerlerini, eğlence yerlerini, halk sağlığına ve çevreye etkisi olan diğer işyerlerini kentin belirli yerlerinde toplamak; hafriyat toprağı ve moloz döküm alanlarını; sıvılaştırılmış petrol gazı (LPG) depolama sahalarını; inşaat malzemeleri, odun, kömür ve hurda depolama alanları ve satış yerlerini belirlemek; bu alan ve yerler ile taşımalarda çevre kirliliği oluşmaması için gereken tedbirleri almak,</li>\r\n<li>Kara, deniz, su ve demiryolu üzerinde işletilen her türlü servis ve toplu taşıma araçları ile taksi sayılarını, bilet ücret ve tarifelerini, zaman ve güzergâhlarını belirlemek; durak yerleri ile karayolu, yol, cadde, sokak, meydan ve benzeri yerler üzerinde araç park yerlerini tespit etmek ve işletmek, işlettirmek veya kiraya vermek,</li>\r\n<li>Kanunların belediyelere verdiği trafik düzenlemesinin gerektirdiği bütün işleri yürütmek,</li>\r\n<li>Belediye mücavir alan sınırları içerisinde 5/11/2008 tarihli ve 5809 sayılı Elektronik Haberleşme Kanunu, 26/9/2011 tarihli ve 655 sayılı Ulaştırma, Denizcilik ve Haberleşme Bakanlığının Teşkilat ve Görevleri Hakkında Kanun Hükmünde Kararname ve ilgili diğer mevzuata göre kuruluş izni verilen alanda tesis edilecek elektronik haberleşme istasyonlarına kent ve yapı estetiği ile elektronik haberleşme hizmetinin gerekleri dikkate alınarak ücret karşılığında yer seçim belgesi vermek,</li>\r\n<li>Belediye sınırları içerisinde, yapı ruhsatı veya yapı kullanma izni hangi idare tarafından verilmiş olursa olsun, hizmete sunulacak olan asansörlerin tescilini yapmak, ilgili teknik mevzuat çerçevesinde yıllık periyodik kontrollerini yapmak ya da yetkilendirilmiş muayene kuruluşları aracılığıyla yaptırmak, gerekli hâllerde asansörleri hizmet dışı bırakmak,</li>\r\n<li>Bisiklet yollarının ve şeritlerinin, bisiklet ve elektrikli skuter park ve şarj istasyonlarının, yaya yollarının ve gürültü bariyerlerinin planlanması, projelendirilmesi, yapımı, bakımı ve onarımıyla ilgili işleri yürütmek,</li>\r\n<li>Vatandaşlara SMS ile bilgilendirme yapılması amacıyla,</li>\r\n<li>Organizasyon, davet ve açılış programlarının yönetilmesi,</li>\r\n<li>Kuruma gelen iş başvurularının özel sektördeki uygun pozisyonlara yönlendirilmesi,</li>\r\n<li>Sosyal yardım faaliyetlerini gerçekleştirebilmek,</li>\r\n<li>Nikah ve evlendirme işlemlerinin gerçekleştirilmesi,</li>\r\n<li>Çocukların psikolog hizmetinden yararlanması ve iletişim kurulması amacıyla,</li>\r\n<li>İnternet sitesi üzerinden bilgilendirme için yayınlanması amacıyla,</li>\r\n<li>Engelli vatandaşlara park yeri ayrılması amacıyla,</li>\r\n<li>Kurumsal iletişim faaliyetleri amacıyla,</li>\r\n<li>Dernekler ile ilgili işlemlerin yürütülmesi amacıyla,</li>\r\n<li>Belediye Meclis üyelerinin kişisel verilerinin işlenmesi amacıyla,</li>\r\n<li>Belediye Başkanları, başkan yardımcıları, müdürler, muhtarlar, etik komisyonu ve arabuluculuk komisyonu üyelerinin bilgilerinin web sitesinden paylaşımı yöntemiyle vatandaşların bilgilendirilmesi amacıyla,</li>\r\n<li>Vatandaş ve Kurum taleplerin alınması ve değerlendirilmesi amaçlarıyla kişisel verileriniz işlenmektedir.</li>\r\n</ul>\r\n\r\n<h3 class=\"tarihce-alt-baslik\">4. Kişisel Verilerin 3. Kişilere Aktarılması</h3>\r\n\r\n<p>Kişisel veri aktarımlarında uygulanacak usul ve esaslar KVK Kanunu\'nun 8. ve 9. maddelerinde düzenlenmiş olup, ilgili kişinin kişisel verileri ve özel nitelikli kişisel verileri, gerektiğinde yurtiçinde yer alan gerçek veya tüzel üçüncü kişilere aktarılabilmektedir. Kurumumuz tarafından toplanan kişisel verilerin yurt dışına aktarımı yapılmamaktadır.</p>\r\n\r\n<p><strong>Kişisel Verilerin Yurt İçindeki Üçüncü Kişilere Aktarılması;</strong><br>\r\nKanunlarda açıkça öngörülmesi, bir sözleşmenin kurulması veya ifasıyla doğrudan doğruya ilgili olması kaydıyla sözleşmenin taraflarına ait kişisel verilerin işlenmesinin gerekli olması, hukuki yükümlülüğümüzün yerine getirilebilmesi için veri işlemenin zorunlu olması, bir hakkın tesisi kullanılması veya korunması için veri işlemenin zorunlu olması, ilgili kişinin temel hak ve özgürlüklerine zarar vermemek kaydıyla meşru menfaatimiz için veri işlenmesinin zorunlu olması işleme şartları sebebiyle özellikle;</p>\r\n\r\n<ul class=\"kvkk-liste\">\r\n<li>T.C. İç İşleri Bakanlığına, Hazine ve Maliye Bakanlığına, Sanayi ve Teknoloji Bakanlığına, Çevre ve Şehircilik Bakanlığına Bağlı ve İlgili Kurumlara,</li>\r\n<li>Yasal denetim süreçleri dahilinde denetim ve teftişle görevli kamu kurum ve kuruluşlarına,</li>\r\n<li>Yetkili kamu kurum ve kuruluşları, adli makamlara ve gerekli olduğu takdirde kolluk kuvvetlerine aktarılabilmektedir.</li>\r\n<li>Bankalara, Belde A.Ş., Hastanelere, Royal Cert Denetim Firmasına, Kocaeli Büyükşehir Belediyesine, TOKİ\'ye aktarılmaktadır.</li>\r\n</ul>\r\n\r\n<h3 class=\"tarihce-alt-baslik\">5. Kişisel Verilerin Güvenliğinin ve Gizliliğinin Sağlanması</h3>\r\n\r\n<p>Kurumumuz, KVK Kanunu\'nun 12. maddesine uygun olarak, işlemekte olduğu kişisel verilerin hukuka aykırı olarak işlenmesini ve kişisel verilere hukuka aykırı erişilmesini önlemek, kişisel verilerin muhafazasını sağlamak için uygun güvenlik düzeyini temin etmeye yönelik gerekli her türlü teknik ve idari tedbirleri almaktadır. İşlenen kişisel verilerin kanuni olmayan yollarla başkaları tarafından elde edilmesi halinde, Kurumumuz bu durumu en kısa sürede ilgili veri sahibine ve Kurul\'a bildirecektir.</p>\r\n\r\n<h3 class=\"tarihce-alt-baslik\">6. Kişisel Verilerin Silinmesi, Yok Edilmesi ve Anonim Hale Getirilmesi</h3>\r\n\r\n<p>KVK Kanunu\'nun 7. maddesi uyarınca, kişisel verilerin ilgili mevzuata uygun olarak işlenmiş olmasına rağmen, işlenmesini gerektiren sebeplerin ortadan kalkması halinde kişisel veriler re\'sen veya kişisel veri sahibinin talebi üzerine Kurumumuz tarafından saklama ve imha politikamıza göre uygun görülecek yöntemle imha edilir.</p>\r\n\r\n<h3 class=\"tarihce-alt-baslik\">7. İlgili Kişinin Sahip Olduğu Haklar</h3>\r\n\r\n<p>KVK Kanunu\'nun 11. maddesi uyarınca, Kurumumuza başvurarak kişisel verileriniz hakkında aşağıdaki konulara ilişkin taleplerde bulunabilirsiniz:</p>\r\n\r\n<ul class=\"kvkk-liste\">\r\n<li>a. Kişisel verilerinin işlenip işlenmediğini öğrenme,</li>\r\n<li>b. Kişisel verileri işlenmişse buna ilişkin bilgi talep etme,</li>\r\n<li>c. Kişisel verilerinin işlenme amacını ve bunların amacına uygun kullanılıp kullanılmadığını öğrenme,</li>\r\n<li>d. Kişisel verilerinin yurt içinde veya yurt dışında aktarıldığı üçüncü kişileri öğrenme,</li>\r\n<li>e. Kişisel verilerinin eksik veya yanlış işlenmiş olması halinde bunların düzeltilmesini isteme ve bu kapsamda yapılan işlemin kişisel verilerin aktarıldığı üçüncü kişilere bildirilmesini isteme,</li>\r\n<li>f. Kişisel verilerinin işlenmesini gerektiren sebeplerin ortadan kalkması halinde bunların silinmesini, yok edilmesini veya anonim hale getirilmesini isteme ve bu kapsamda yapılan işlemin kişisel verilerin aktarıldığı üçüncü kişilere bildirilmesini isteme,</li>\r\n<li>g. İşlenen verilerinin münhasıran otomatik sistemler vasıtasıyla analiz edilmesi suretiyle veri sahibinin aleyhine bir sonucun ortaya çıkmasına itiraz etme,</li>\r\n<li>h. Kişisel verilerinin kanuna aykırı olarak işlenmesi sebebiyle zarara uğraması halinde zararın giderilmesini talep etme.</li>\r\n</ul>\r\n\r\n<p>İlgili kişiler kanun kapsamındaki başvuruları ve taleplerini, \"https://www.gebze.bel.tr\" web adresinde bulunan \"Kişisel Verilerin Korunması Kanunu Uyarınca Başvuru Formu\"nu doldurarak;</p>\r\n\r\n<ul class=\"kvkk-liste\">\r\n<li>Güzeller Mahallesi. Bahar Cad. N:1 41400 Gebze/Kocaeli adresine bizzat teslim edebilir veya Noter kanalıyla iletebilir,</li>\r\n<li>gebzebelediyesi@hs01.kep.tr adresine güvenli elektronik imzalı ya da mobil imzalı olarak, kayıtlı elektronik postayla (KEP) veya kvkk@gebze.bel.tr mail adresine ilgili kişi tarafından veri sorumlusuna daha önce bildirilen ve veri sorumlusunun sisteminde kayıtlı bulunan elektronik posta adresini kullanmak suretiyle iletebilirsiniz.</li>\r\n</ul>\r\n\r\n<p>Kurumumuz başvuru taleplerini Kanun\'un 13. maddesine uygun olarak, talebin niteliğine göre ve en geç 30 (otuz) gün içinde ücretsiz olarak sonuçlandıracaktır. Talebin reddedilmesi halinde, red nedeni/nedenleri yazılı olarak veya elektronik ortamda gerekçeleriyle bildirilir.</p>\r\n\r\n<p>İşbu Aydınlatma Metni, gerekli görüldüğü hallerde Kurumumuz tarafından revize edilebilir. Revizyonun söz konusu olduğu hallerde ise, bu hususa ilişkin olarak tarafınıza bilgilendirme yapılacaktır. Aydınlatma Metni\'nin en güncel haline https://www.gebze.bel.tr linkinden, ulaşabilirsiniz.</p>\r\n');

